CREATE SCHEMA IF NOT EXISTS aureva;
REVOKE ALL ON SCHEMA aureva FROM PUBLIC,anon,authenticated;
SET search_path TO aureva;
CREATE TABLE users(id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('donor','manager','approver')));
ALTER TABLE users ENABLE ROW LEVEL SECURITY;
CREATE TABLE sessions(token TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires BIGINT NOT NULL);
ALTER TABLE sessions ENABLE ROW LEVEL SECURITY;
CREATE TABLE attempts(key TEXT PRIMARY KEY, count BIGINT NOT NULL, expires BIGINT NOT NULL);
ALTER TABLE attempts ENABLE ROW LEVEL SECURITY;
CREATE TABLE campaigns(id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL, location TEXT NOT NULL, target BIGINT NOT NULL CHECK(target>0), owner_id TEXT NOT NULL REFERENCES users(id), created TEXT NOT NULL);
ALTER TABLE campaigns ENABLE ROW LEVEL SECURITY;
CREATE TABLE donations(id TEXT PRIMARY KEY, campaign_id TEXT NOT NULL REFERENCES campaigns(id), donor_id TEXT NOT NULL REFERENCES users(id), amount BIGINT NOT NULL CHECK(amount>0), reference TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created TEXT NOT NULL, UNIQUE(campaign_id,reference));
ALTER TABLE donations ENABLE ROW LEVEL SECURITY;
CREATE TABLE expenses(id TEXT PRIMARY KEY, campaign_id TEXT NOT NULL REFERENCES campaigns(id), creator_id TEXT NOT NULL REFERENCES users(id), amount BIGINT NOT NULL CHECK(amount>0), purpose TEXT NOT NULL, vendor TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', reason TEXT, reviewer_id TEXT REFERENCES users(id), created TEXT NOT NULL);
ALTER TABLE expenses ENABLE ROW LEVEL SECURITY;
CREATE TABLE audit(id BIGSERIAL PRIMARY KEY, actor_id TEXT NOT NULL REFERENCES users(id), action TEXT NOT NULL, entity_id TEXT NOT NULL, detail TEXT NOT NULL, created TEXT NOT NULL);
ALTER TABLE audit ENABLE ROW LEVEL SECURITY;
CREATE TABLE documents(id TEXT PRIMARY KEY,expense_id TEXT UNIQUE NOT NULL REFERENCES expenses(id),filename TEXT NOT NULL,mime TEXT NOT NULL,content BYTEA NOT NULL,sha256 TEXT NOT NULL,ai_status TEXT NOT NULL DEFAULT 'pending',ai_result TEXT,ai_error TEXT,model TEXT,attempt_started BIGINT,created TEXT NOT NULL);
ALTER TABLE documents ENABLE ROW LEVEL SECURITY;
CREATE TABLE attestations(id TEXT PRIMARY KEY,entity_type TEXT NOT NULL,entity_id TEXT UNIQUE NOT NULL,payload TEXT NOT NULL,digest TEXT UNIQUE NOT NULL,status TEXT NOT NULL DEFAULT 'pending',tx_hash TEXT,raw_tx TEXT,nonce BIGINT,chain_id BIGINT,contract TEXT,block_number BIGINT,error TEXT,created TEXT NOT NULL);
ALTER TABLE attestations ENABLE ROW LEVEL SECURITY;
CREATE TABLE reports(id TEXT PRIMARY KEY,campaign_id TEXT NOT NULL REFERENCES campaigns(id),snapshot TEXT NOT NULL,pdf BYTEA NOT NULL,pdf_hash TEXT NOT NULL,created TEXT NOT NULL);
ALTER TABLE reports ENABLE ROW LEVEL SECURITY;
CREATE INDEX donations_campaign ON donations(campaign_id,status);
CREATE INDEX donations_donor ON donations(donor_id);
CREATE INDEX expenses_campaign ON expenses(campaign_id,status);
CREATE INDEX campaigns_owner ON campaigns(owner_id);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE INDEX documents_sha ON documents(sha256);
CREATE INDEX reports_campaign ON reports(campaign_id);
REVOKE ALL ON ALL TABLES IN SCHEMA aureva FROM PUBLIC,anon,authenticated;
